{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "Merck-3, a hydroxyethylamine peptidomimetic with benzyl and amide groups similar to the query, was undetectable in mouse brain after IV dosing despite plasma ~1.3 µM and was identified as a P-gp substrate; brain levels rose in mdr1A-deficient mice, directly supporting poor CNS access and efflux liability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Sacubitril, a peptidomimetic prodrug with amide and ester functionality, showed very low CNS penetration in non-human primates with CSF:plasma ratio ≤0.0044 and brain:plasma ratio ≤0.0326, indicating that systemic exposure does not translate into meaningful brain access for this structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Carfilzomib, a peptide-like high-molecular-weight drug with multiple amides, failed to suppress proteasome activity in rat brain after IV administration, demonstrating poor blood-brain barrier crossing for large peptidomimetics.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "HSK21542, a peptide-like compound, showed minimal brain penetration with a brain/plasma concentration ratio of 0.001, consistent with very limited CNS access for this type of polar peptidomimetic scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Sacubitrilat was detected in human CSF, indicating that some related peptidomimetic molecules can cross the BBB in humans; however, detection does not establish meaningful exposure, and NHP data show very low CSF and brain ratios.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C11"],
      "claim": "Inhibitor 6, a hydroxyethylamine BACE inhibitor with benzyl and amide features, achieved a brain/plasma ratio of 0.69 in mice, showing that some analogues in this chemical space can achieve appreciable brain exposure despite being peptidomimetic.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a large, polar peptidomimetic with multiple amides, a hydroxyethylene isostere, and a cyclic urea; direct analogues with similar scaffolds predominantly show very low brain/CSF exposure and P-gp efflux, so meaningful CNS access is unlikely.",
  "evidence_gaps": [
    "No direct brain, CSF, or unbound brain:plasma measurement exists for the query molecule.",
    "All experimental analogues have Morgan similarity below 0.3, limiting quantitative transferability.",
    "The query's specific transporter phenotype (P-gp, BCRP) has not been experimentally determined.",
    "Human CNS exposure data for the query are absent."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

